func TestGetTraceExporter(t *testing.T) {
	tests := []struct {
		name    string
		cfg     *config.Config
		wantErr error
	}{
		{
			name: "Jaeger",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingJaeger,
					Jaeger: config.JaegerTracingConfig{
						Host: "localhost",
						Port: 6831,
					},
				},
			},
		},
		{
			name: "Zipkin",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingZipkin,
					Zipkin: config.ZipkinTracingConfig{
						Endpoint: "http://localhost:9411/api/v2/spans",
					},
				},
			},
		},
		{
			name: "OTLP HTTP",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "http://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP HTTPS",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "https://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP GRPC",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "grpc://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP default",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "Unsupported Exporter",
			cfg: &config.Config{
				Tracing: config.TracingConfig{},
			},
			wantErr: errors.New("unsupported tracing exporter: 0"),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			exp, expFunc, err := tracing.GetExporter(context.Background(), &tt.cfg.Tracing)
			if tt.wantErr != nil {
				assert.EqualError(t, err, tt.wantErr.Error())
				return
			}
			t.Cleanup(func() {
				err := expFunc(context.Background())
				assert.NoError(t, err)
			})
			assert.NoError(t, err)
			assert.NotNil(t, exp)
			assert.NotNil(t, expFunc)

		})
	}
}
